trace.command:
cd /workspace/graphic && python3 - <<'EOF'
p='css/template.css'; s=open(p).read()
s=s.replace('''  font-size: calc(48px * var(--scale) * var(--type-scale));
  font-weight: 800;
  line-height: 1;''','''  font-size: calc(46px * var(--scale) * var(--type-scale));
  font-weight: 800;
  line-height: 1.05;
  flex-shrink: 0;
  display: -webkit-box;            /* a bounded one-row figure: the stage fit leaves it at its size */
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;''')
s=s.replace('''  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;''','''  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
  display: -webkit-box;            /* a bounded one-row chip: the stage fit leaves it at its size */
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;''')
s=s.replace('''  padding: calc(5px * var(--scale)) calc(9px * var(--scale)) calc(4px * var(--scale));
  border-radius: calc(3px * var(--scale));''','''  padding: calc(5px * var(--scale)) calc(8px * var(--scale)) calc(4px * var(--scale));
  border-radius: calc(3px * var(--scale));''')
open(p,'w').write(s)
EOF
export NOACG_URL=https://noacg.studio && noacg validate /workspace/graphic --screenshots /workspace/shots 2>&1 | grep -E "OK -|ERR|WARN" | cut -c1-200
